class Solution:
    def minSwapsThreeColours(self, balls: List[int]) -> int:
        n0, n1 = balls.count(0), balls.count(1)
        c = [[0] * 3 for _ in range(3)]
        for i, b in enumerate(balls):
            need = 0 if i < n0 else (1 if i < n0 + n1 else 2)
            c[b][need] += 1
        moves = 0
        for a in range(3):
            for b in range(a + 1, 3):
                m = min(c[a][b], c[b][a])
                moves += m
                c[a][b] -= m
                c[b][a] -= m
        left = c[0][1] + c[0][2] + c[1][0] + c[1][2] + c[2][0] + c[2][1]
        return moves + 2 * left // 3

