int minSwapsThreeColours(int* balls, int ballsSize) {
    int n0 = 0, n1 = 0;
    for (int i = 0; i < ballsSize; i++) { if (balls[i] == 0) n0++; else if (balls[i] == 1) n1++; }
    int c[3][3] = {{0}};
    for (int i = 0; i < ballsSize; i++) {
        int need = i < n0 ? 0 : (i < n0 + n1 ? 1 : 2);
        c[balls[i]][need]++;
    }
    int moves = 0;
    for (int a = 0; a < 3; a++)
        for (int b = a + 1; b < 3; b++) {
            int m = c[a][b] < c[b][a] ? c[a][b] : c[b][a];
            moves += m;
            c[a][b] -= m;
            c[b][a] -= m;
        }
    int left = c[0][1] + c[0][2] + c[1][0] + c[1][2] + c[2][0] + c[2][1];
    return moves + 2 * left / 3;
}
